insert into public.translations (locale, key, value) values
  ('pt-BR', 'grants.title', $json$"Permissões deste chat"$json$::jsonb),
  ('en', 'grants.title', $json$"Permissions for this chat"$json$::jsonb),
  ('es', 'grants.title', $json$"Permisos de este chat"$json$::jsonb),
  ('zh-CN', 'grants.title', $json$"此聊天的权限"$json$::jsonb),
  ('hi', 'grants.title', $json$"इस चैट की अनुमतियाँ"$json$::jsonb),
  ('ar', 'grants.title', $json$"أذونات هذه المحادثة"$json$::jsonb),
  ('fr', 'grants.title', $json$"Autorisations de ce chat"$json$::jsonb),
  ('ru', 'grants.title', $json$"Разрешения для этого чата"$json$::jsonb),
  ('ja', 'grants.title', $json$"このチャットの許可"$json$::jsonb),
  ('de', 'grants.title', $json$"Berechtigungen für diesen Chat"$json$::jsonb),
  ('pt-BR', 'grants.hint', $json$"Ficam ligadas para todas as mensagens deste chat, no modo desenvolvimento, até você desligar. Sem nada ligado, quando o agente é barrado o JayV pergunta acima da caixa de mensagem se executa, nega ou sempre permite o comando."$json$::jsonb),
  ('en', 'grants.hint', $json$"They stay on for every message in this chat, in development mode, until you turn them off. With nothing on, when the agent is blocked JayV asks above the message box whether to run, deny or always allow the command."$json$::jsonb),
  ('es', 'grants.hint', $json$"Quedan activadas para todos los mensajes de este chat, en modo desarrollo, hasta que las desactives. Sin nada activado, cuando se bloquea al agente, JayV pregunta encima del cuadro de mensaje si ejecuta, deniega o permite siempre el comando."$json$::jsonb),
  ('zh-CN', 'grants.hint', $json$"在开发模式下，它们会对此聊天中的每条消息保持开启，直到你关闭。未开启任何权限时，如果智能体被拦截，JayV 会在消息框上方询问是执行、拒绝还是始终允许该命令。"$json$::jsonb),
  ('hi', 'grants.hint', $json$"ये विकास मोड में इस चैट के हर संदेश के लिए चालू रहती हैं, जब तक आप इन्हें बंद नहीं करते। कुछ भी चालू न होने पर, एजेंट के रुकने पर JayV संदेश बॉक्स के ऊपर पूछता है कि कमांड चलाएँ, अस्वीकार करें या हमेशा अनुमति दें।"$json$::jsonb),
  ('ar', 'grants.hint', $json$"تبقى مفعّلة لكل رسالة في هذه المحادثة، في وضع التطوير، حتى توقفها. وعند عدم تفعيل شيء، إذا مُنع الوكيل يسأل JayV فوق صندوق الرسالة هل يُنفَّذ الأمر أم يُرفض أم يُسمح به دائمًا."$json$::jsonb),
  ('fr', 'grants.hint', $json$"Elles restent activées pour chaque message de ce chat, en mode développement, jusqu'à ce que vous les désactiviez. Sans rien d'activé, quand l'agent est bloqué, JayV demande au-dessus de la zone de message s'il faut exécuter, refuser ou toujours autoriser la commande."$json$::jsonb),
  ('ru', 'grants.hint', $json$"Они остаются включёнными для каждого сообщения в этом чате, в режиме разработки, пока вы их не отключите. Если ничего не включено, при блокировке агента JayV спрашивает над полем сообщения: выполнить, отклонить или всегда разрешать команду."$json$::jsonb),
  ('ja', 'grants.hint', $json$"開発モードでは、オフにするまでこのチャットのすべてのメッセージでオンのままになります。何もオンにしていない場合、エージェントがブロックされると、JayV がメッセージ欄の上で、コマンドを実行するか、拒否するか、常に許可するかを尋ねます。"$json$::jsonb),
  ('de', 'grants.hint', $json$"Sie bleiben im Entwicklungsmodus für jede Nachricht in diesem Chat eingeschaltet, bis Sie sie ausschalten. Ist nichts eingeschaltet, fragt JayV bei einem blockierten Agenten über dem Nachrichtenfeld, ob der Befehl ausgeführt, abgelehnt oder immer erlaubt wird."$json$::jsonb),
  ('pt-BR', 'grants.commands.hint', $json$"Escolha os comandos a liberar neste chat."$json$::jsonb),
  ('en', 'grants.commands.hint', $json$"Pick the commands to allow in this chat."$json$::jsonb),
  ('es', 'grants.commands.hint', $json$"Elige los comandos que se permiten en este chat."$json$::jsonb),
  ('zh-CN', 'grants.commands.hint', $json$"选择在此聊天中允许的命令。"$json$::jsonb),
  ('hi', 'grants.commands.hint', $json$"इस चैट में अनुमति देने के लिए कमांड चुनें।"$json$::jsonb),
  ('ar', 'grants.commands.hint', $json$"اختر الأوامر المسموح بها في هذه المحادثة."$json$::jsonb),
  ('fr', 'grants.commands.hint', $json$"Choisissez les commandes à autoriser dans ce chat."$json$::jsonb),
  ('ru', 'grants.commands.hint', $json$"Выберите команды, разрешённые в этом чате."$json$::jsonb),
  ('ja', 'grants.commands.hint', $json$"このチャットで許可するコマンドを選びます。"$json$::jsonb),
  ('de', 'grants.commands.hint', $json$"Wählen Sie die Befehle, die in diesem Chat erlaubt sind."$json$::jsonb),
  ('pt-BR', 'palette.commandPermissions', $json$"Permissões de comandos deste chat"$json$::jsonb),
  ('en', 'palette.commandPermissions', $json$"Command permissions for this chat"$json$::jsonb),
  ('es', 'palette.commandPermissions', $json$"Permisos de comandos de este chat"$json$::jsonb),
  ('zh-CN', 'palette.commandPermissions', $json$"此聊天的命令权限"$json$::jsonb),
  ('hi', 'palette.commandPermissions', $json$"इस चैट की कमांड अनुमतियाँ"$json$::jsonb),
  ('ar', 'palette.commandPermissions', $json$"أذونات الأوامر لهذه المحادثة"$json$::jsonb),
  ('fr', 'palette.commandPermissions', $json$"Autorisations de commandes de ce chat"$json$::jsonb),
  ('ru', 'palette.commandPermissions', $json$"Разрешения на команды для этого чата"$json$::jsonb),
  ('ja', 'palette.commandPermissions', $json$"このチャットのコマンド許可"$json$::jsonb),
  ('de', 'palette.commandPermissions', $json$"Befehlsberechtigungen für diesen Chat"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Sino e ajuda ao lado do logotipo"$json$::jsonb),
  ('en', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Bell and help next to the logo"$json$::jsonb),
  ('es', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Campana y ayuda junto al logotipo"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.sidebarHeaderButtons.title', $json$"铃铛和帮助按钮移到标志旁"$json$::jsonb),
  ('hi', 'whatsNew.item.sidebarHeaderButtons.title', $json$"घंटी और सहायता लोगो के बगल में"$json$::jsonb),
  ('ar', 'whatsNew.item.sidebarHeaderButtons.title', $json$"الجرس والمساعدة بجانب الشعار"$json$::jsonb),
  ('fr', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Cloche et aide à côté du logo"$json$::jsonb),
  ('ru', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Колокольчик и справка рядом с логотипом"$json$::jsonb),
  ('ja', 'whatsNew.item.sidebarHeaderButtons.title', $json$"ベルとヘルプをロゴの横へ"$json$::jsonb),
  ('de', 'whatsNew.item.sidebarHeaderButtons.title', $json$"Glocke und Hilfe neben dem Logo"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"O sino das notificações e o botão de ajuda (?) foram para o alto da lateral, à direita do logotipo do JayV. O perfil e as Configurações continuam embaixo."$json$::jsonb),
  ('en', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"The notifications bell and the help button (?) moved to the top of the sidebar, to the right of the JayV logo. The profile and Settings stay at the bottom."$json$::jsonb),
  ('es', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"La campana de notificaciones y el botón de ayuda (?) pasaron a la parte superior de la barra lateral, a la derecha del logotipo de JayV. El perfil y los Ajustes siguen abajo."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"通知铃铛和帮助按钮 (?) 移到了侧边栏顶部，位于 JayV 标志的右侧。个人资料和设置仍在底部。"$json$::jsonb),
  ('hi', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"सूचनाओं की घंटी और सहायता बटन (?) साइडबार के ऊपर, JayV लोगो के दाईं ओर आ गए हैं। प्रोफ़ाइल और सेटिंग्स नीचे ही रहती हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"انتقل جرس الإشعارات وزر المساعدة (?) إلى أعلى الشريط الجانبي، بجانب شعار JayV. يبقى الملف الشخصي والإعدادات في الأسفل."$json$::jsonb),
  ('fr', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"La cloche des notifications et le bouton d'aide (?) sont passés en haut de la barre latérale, à droite du logo JayV. Le profil et les Réglages restent en bas."$json$::jsonb),
  ('ru', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"Колокольчик уведомлений и кнопка справки (?) переместились в верх боковой панели, справа от логотипа JayV. Профиль и настройки остались внизу."$json$::jsonb),
  ('ja', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"通知のベルとヘルプボタン (?) をサイドバー上部の JayV ロゴの右側に移しました。プロフィールと設定は下に残ります。"$json$::jsonb),
  ('de', 'whatsNew.item.sidebarHeaderButtons.detail', $json$"Die Benachrichtigungsglocke und die Hilfe-Schaltfläche (?) sind an den Anfang der Seitenleiste gewandert, rechts neben das JayV-Logo. Profil und Einstellungen bleiben unten."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.chatWidePermissions.title', $json$"Permissões valem para o chat inteiro"$json$::jsonb),
  ('en', 'whatsNew.item.chatWidePermissions.title', $json$"Permissions last for the whole chat"$json$::jsonb),
  ('es', 'whatsNew.item.chatWidePermissions.title', $json$"Los permisos valen para todo el chat"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.chatWidePermissions.title', $json$"权限对整个聊天有效"$json$::jsonb),
  ('hi', 'whatsNew.item.chatWidePermissions.title', $json$"अनुमतियाँ पूरे चैट के लिए लागू"$json$::jsonb),
  ('ar', 'whatsNew.item.chatWidePermissions.title', $json$"الأذونات تسري على المحادثة كلها"$json$::jsonb),
  ('fr', 'whatsNew.item.chatWidePermissions.title', $json$"Les autorisations valent pour tout le chat"$json$::jsonb),
  ('ru', 'whatsNew.item.chatWidePermissions.title', $json$"Разрешения действуют на весь чат"$json$::jsonb),
  ('ja', 'whatsNew.item.chatWidePermissions.title', $json$"許可はチャット全体に有効"$json$::jsonb),
  ('de', 'whatsNew.item.chatWidePermissions.title', $json$"Berechtigungen gelten für den ganzen Chat"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.chatWidePermissions.detail', $json$"O que você liga em Permissões (rodar comandos, Git, rede e comandos específicos) agora continua ligado em todas as mensagens do chat até você desligar, e não só na próxima. A escolha fica gravada neste computador, por chat, e o que a organização bloqueia continua valendo."$json$::jsonb),
  ('en', 'whatsNew.item.chatWidePermissions.detail', $json$"What you turn on in Permissions (run commands, Git, network and specific commands) now stays on for every message in the chat until you turn it off, not only the next one. The choice is kept on this computer, per chat, and what the organization blocks still applies."$json$::jsonb),
  ('es', 'whatsNew.item.chatWidePermissions.detail', $json$"Lo que activas en Permisos (ejecutar comandos, Git, red y comandos concretos) ahora sigue activado en todos los mensajes del chat hasta que lo desactives, no solo en el siguiente. La elección se guarda en este equipo, por chat, y lo que bloquea la organización sigue vigente."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.chatWidePermissions.detail', $json$"你在“权限”中开启的内容（运行命令、Git、网络和特定命令）现在会对聊天中的每条消息保持开启，直到你关闭，而不只是下一条。该选择按聊天保存在这台电脑上，组织阻止的内容仍然有效。"$json$::jsonb),
  ('hi', 'whatsNew.item.chatWidePermissions.detail', $json$"अनुमतियों में आप जो चालू करते हैं (कमांड चलाना, Git, नेटवर्क और विशिष्ट कमांड) वह अब चैट के हर संदेश के लिए, बंद करने तक, चालू रहता है, केवल अगले संदेश के लिए नहीं। चुनाव इस कंप्यूटर पर, चैट के अनुसार, सहेजा जाता है और संगठन जो अवरुद्ध करता है वह लागू रहता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.chatWidePermissions.detail', $json$"ما تفعّله في الأذونات (تشغيل الأوامر وGit والشبكة وأوامر محددة) يبقى الآن مفعّلًا لكل رسائل المحادثة حتى توقفه، وليس للرسالة التالية فقط. يُحفظ الاختيار على هذا الحاسوب لكل محادثة، ويظل ما تحظره المؤسسة ساريًا."$json$::jsonb),
  ('fr', 'whatsNew.item.chatWidePermissions.detail', $json$"Ce que vous activez dans Autorisations (exécuter des commandes, Git, réseau et commandes précises) reste désormais activé pour chaque message du chat jusqu'à ce que vous le désactiviez, et non plus pour le seul message suivant. Le choix est conservé sur cet ordinateur, par chat, et ce que l'organisation bloque reste appliqué."$json$::jsonb),
  ('ru', 'whatsNew.item.chatWidePermissions.detail', $json$"То, что вы включаете в «Разрешениях» (запуск команд, Git, сеть и отдельные команды), теперь остаётся включённым для каждого сообщения чата, пока вы это не отключите, а не только для следующего. Выбор сохраняется на этом компьютере отдельно для каждого чата, а блокировки организации по-прежнему действуют."$json$::jsonb),
  ('ja', 'whatsNew.item.chatWidePermissions.detail', $json$"「許可」でオンにしたもの（コマンドの実行、Git、ネットワーク、特定のコマンド）は、次のメッセージだけでなく、オフにするまでチャットのすべてのメッセージでオンのままになります。選択はチャットごとにこのコンピューターに保存され、組織によるブロックは引き続き有効です。"$json$::jsonb),
  ('de', 'whatsNew.item.chatWidePermissions.detail', $json$"Was Sie unter Berechtigungen einschalten (Befehle ausführen, Git, Netzwerk und bestimmte Befehle), bleibt jetzt für jede Nachricht im Chat eingeschaltet, bis Sie es ausschalten, nicht nur für die nächste. Die Auswahl wird pro Chat auf diesem Computer gespeichert, und was die Organisation blockiert, gilt weiterhin."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Respostas sempre no seu idioma"$json$::jsonb),
  ('en', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Replies always in your language"$json$::jsonb),
  ('es', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Respuestas siempre en tu idioma"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.replyLanguageEverywhere.title', $json$"回复始终使用你的语言"$json$::jsonb),
  ('hi', 'whatsNew.item.replyLanguageEverywhere.title', $json$"उत्तर हमेशा आपकी भाषा में"$json$::jsonb),
  ('ar', 'whatsNew.item.replyLanguageEverywhere.title', $json$"الردود دائمًا بلغتك"$json$::jsonb),
  ('fr', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Réponses toujours dans votre langue"$json$::jsonb),
  ('ru', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Ответы всегда на вашем языке"$json$::jsonb),
  ('ja', 'whatsNew.item.replyLanguageEverywhere.title', $json$"返信は常にあなたの言語で"$json$::jsonb),
  ('de', 'whatsNew.item.replyLanguageEverywhere.title', $json$"Antworten immer in Ihrer Sprache"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"O lembrete do idioma do app agora vai em todo pedido, inclusive nas linhas que o próprio JayV escreve quando você aprova um comando ou responde a uma pergunta (em inglês, e o modelo as seguia). O app também avisa o núcleo de novo se o primeiro aviso se perder. Modelos que leem arquivos ou documentação em inglês continuam respondendo no idioma que você escolheu."$json$::jsonb),
  ('en', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"The app-language reminder now goes with every request, including the lines JayV writes itself when you approve a command or answer a question (in English, and the model followed them). The app also tells the core again if the first notice is lost. Models that read English files or documentation keep answering in the language you chose."$json$::jsonb),
  ('es', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"El recordatorio del idioma de la app ahora va en cada petición, también en las líneas que escribe el propio JayV cuando apruebas un comando o respondes una pregunta (en inglés, y el modelo las seguía). La app además avisa de nuevo al núcleo si se pierde el primer aviso. Los modelos que leen archivos o documentación en inglés siguen respondiendo en el idioma que elegiste."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"应用语言提醒现在会随每个请求发送，包括你批准命令或回答问题时 JayV 自己写的那些行（是英文的，模型会跟着用英文）。如果第一次通知丢失，应用也会再次通知核心。读取英文文件或文档的模型会继续使用你选择的语言回答。"$json$::jsonb),
  ('hi', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"ऐप की भाषा का अनुस्मारक अब हर अनुरोध के साथ जाता है, उन पंक्तियों में भी जो JayV खुद लिखता है जब आप कमांड स्वीकृत करते हैं या प्रश्न का उत्तर देते हैं (वे अंग्रेज़ी में थीं और मॉडल उनका अनुसरण करता था)। पहली सूचना खो जाए तो ऐप कोर को फिर बताता है। अंग्रेज़ी फ़ाइलें या दस्तावेज़ पढ़ने वाले मॉडल आपकी चुनी भाषा में ही उत्तर देते रहते हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"يُرسل تذكير لغة التطبيق الآن مع كل طلب، بما في ذلك السطور التي يكتبها JayV بنفسه عندما توافق على أمر أو تجيب عن سؤال (كانت بالإنجليزية وكان النموذج يتبعها). كما يُعلم التطبيق النواة مرة أخرى إذا ضاع الإشعار الأول. وتواصل النماذج التي تقرأ ملفات أو توثيقًا بالإنجليزية الرد باللغة التي اخترتها."$json$::jsonb),
  ('fr', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"Le rappel de la langue de l'app accompagne désormais chaque requête, y compris les lignes que JayV écrit lui-même quand vous approuvez une commande ou répondez à une question (en anglais, et le modèle les suivait). L'app prévient aussi à nouveau le cœur si le premier avis se perd. Les modèles qui lisent des fichiers ou de la documentation en anglais continuent de répondre dans la langue choisie."$json$::jsonb),
  ('ru', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"Напоминание о языке приложения теперь идёт с каждым запросом, в том числе со строками, которые JayV пишет сам, когда вы одобряете команду или отвечаете на вопрос (они были на английском, и модель следовала им). Если первое уведомление потеряно, приложение сообщает ядру ещё раз. Модели, читающие английские файлы или документацию, продолжают отвечать на выбранном вами языке."$json$::jsonb),
  ('ja', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"アプリの言語のリマインダーが、コマンドを承認したり質問に答えたりしたときに JayV 自身が書く行（英語で、モデルもそれに引きずられていました）を含め、すべてのリクエストに付くようになりました。最初の通知が失われた場合は、アプリがコアにもう一度伝えます。英語のファイルやドキュメントを読むモデルも、選んだ言語で答え続けます。"$json$::jsonb),
  ('de', 'whatsNew.item.replyLanguageEverywhere.detail', $json$"Die Erinnerung an die App-Sprache wird jetzt bei jeder Anfrage mitgeschickt, auch bei den Zeilen, die JayV selbst schreibt, wenn Sie einen Befehl genehmigen oder eine Frage beantworten (auf Englisch, und das Modell folgte ihnen). Geht die erste Mitteilung verloren, sagt die App dem Kern erneut Bescheid. Modelle, die englische Dateien oder Dokumentation lesen, antworten weiter in der gewählten Sprache."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.codeAndFiles.title', $json$"Código e arquivos reconhecidos em toda resposta"$json$::jsonb),
  ('en', 'whatsNew.item.codeAndFiles.title', $json$"Code and files recognized in every reply"$json$::jsonb),
  ('es', 'whatsNew.item.codeAndFiles.title', $json$"Código y archivos reconocidos en cada respuesta"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.codeAndFiles.title', $json$"每条回复都能识别代码和文件"$json$::jsonb),
  ('hi', 'whatsNew.item.codeAndFiles.title', $json$"हर उत्तर में कोड और फ़ाइलों की पहचान"$json$::jsonb),
  ('ar', 'whatsNew.item.codeAndFiles.title', $json$"التعرف على الكود والملفات في كل رد"$json$::jsonb),
  ('fr', 'whatsNew.item.codeAndFiles.title', $json$"Code et fichiers reconnus dans chaque réponse"$json$::jsonb),
  ('ru', 'whatsNew.item.codeAndFiles.title', $json$"Код и файлы распознаются в каждом ответе"$json$::jsonb),
  ('ja', 'whatsNew.item.codeAndFiles.title', $json$"すべての返信でコードとファイルを認識"$json$::jsonb),
  ('de', 'whatsNew.item.codeAndFiles.title', $json$"Code und Dateien in jeder Antwort erkannt"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.codeAndFiles.detail', $json$"A resposta é formatada enquanto é escrita, não só no fim. Os selos de arquivo agora cobrem caminhos com espaço, caminhos do Windows, .env.example, intervalos de linhas (arquivo.ts:10-20) e links para arquivos; os blocos de código cobrem cercas sem fechar, recuadas, com ~~~ ou mais longas, e o texto também mostra itálico e código com crase dupla."$json$::jsonb),
  ('en', 'whatsNew.item.codeAndFiles.detail', $json$"The reply is formatted while it is being written, not only at the end. File chips now cover paths with spaces, Windows paths, .env.example, line ranges (file.ts:10-20) and links to files; code blocks cover unclosed, indented, ~~~ and longer fences, and the text also shows italics and double-backtick code."$json$::jsonb),
  ('es', 'whatsNew.item.codeAndFiles.detail', $json$"La respuesta se formatea mientras se escribe, no solo al final. Las etiquetas de archivo ahora cubren rutas con espacios, rutas de Windows, .env.example, rangos de líneas (archivo.ts:10-20) y enlaces a archivos; los bloques de código cubren vallas sin cerrar, con sangría, con ~~~ o más largas, y el texto también muestra cursiva y código con doble acento grave."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.codeAndFiles.detail', $json$"回复在编写过程中就会被格式化，而不仅是在结束时。文件标签现在支持带空格的路径、Windows 路径、.env.example、行范围（file.ts:10-20）和文件链接；代码块支持未闭合、缩进、~~~ 和更长的围栏，文本还能显示斜体和双反引号代码。"$json$::jsonb),
  ('hi', 'whatsNew.item.codeAndFiles.detail', $json$"उत्तर लिखे जाते समय ही फ़ॉर्मैट होता है, केवल अंत में नहीं। फ़ाइल चिप अब स्पेस वाले पथ, Windows पथ, .env.example, पंक्ति सीमाएँ (file.ts:10-20) और फ़ाइलों के लिंक सँभालते हैं; कोड ब्लॉक बिना बंद, इंडेंट किए, ~~~ और लंबे बाड़ सँभालते हैं, और पाठ में इटैलिक व दोहरे बैकटिक का कोड भी दिखता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.codeAndFiles.detail', $json$"يُنسَّق الرد أثناء كتابته وليس في النهاية فقط. تغطي شارات الملفات الآن المسارات التي فيها مسافات ومسارات Windows و.env.example ونطاقات الأسطر (file.ts:10-20) وروابط الملفات؛ وتغطي كتل الكود الأسوار غير المغلقة والمزاحة وذات ~~~ والأطول، ويعرض النص أيضًا الخط المائل والكود بعلامتي اقتباس خلفيتين."$json$::jsonb),
  ('fr', 'whatsNew.item.codeAndFiles.detail', $json$"La réponse est mise en forme pendant qu'elle s'écrit, pas seulement à la fin. Les pastilles de fichier couvrent désormais les chemins avec espaces, les chemins Windows, .env.example, les plages de lignes (fichier.ts:10-20) et les liens vers des fichiers ; les blocs de code couvrent les clôtures non fermées, indentées, en ~~~ ou plus longues, et le texte affiche aussi l'italique et le code à double accent grave."$json$::jsonb),
  ('ru', 'whatsNew.item.codeAndFiles.detail', $json$"Ответ форматируется по мере написания, а не только в конце. Значки файлов теперь охватывают пути с пробелами, пути Windows, .env.example, диапазоны строк (file.ts:10-20) и ссылки на файлы; блоки кода — незакрытые, с отступом, с ~~~ и более длинные ограждения, а в тексте отображаются курсив и код в двойных обратных кавычках."$json$::jsonb),
  ('ja', 'whatsNew.item.codeAndFiles.detail', $json$"返信は最後だけでなく、書かれている途中で整形されます。ファイルのチップは、スペースを含むパス、Windows のパス、.env.example、行範囲（file.ts:10-20）、ファイルへのリンクに対応し、コードブロックは閉じていないフェンス、インデント、~~~、より長いフェンスに対応します。本文では斜体と二重バッククォートのコードも表示されます。"$json$::jsonb),
  ('de', 'whatsNew.item.codeAndFiles.detail', $json$"Die Antwort wird schon beim Schreiben formatiert, nicht erst am Ende. Datei-Chips erfassen jetzt Pfade mit Leerzeichen, Windows-Pfade, .env.example, Zeilenbereiche (datei.ts:10-20) und Links auf Dateien; Codeblöcke erfassen nicht geschlossene, eingerückte, ~~~- und längere Zäune, und der Text zeigt auch Kursivschrift und Code mit doppeltem Backtick."$json$::jsonb),
  ('pt-BR', 'docs.commandPermissions.usage', $json$"No site, abra a organização e use a aba Permissões: escolha o escopo (a organização inteira ou um repositório), marque um programa para bloquear todos os subcomandos dele ou só os subcomandos que não devem rodar, acrescente outros comandos, um por linha, e salve. Um repositório só pode bloquear mais do que a organização. No chat, abra Permissões ao lado do modo de trabalho (ou Ctrl+K › Permissões de comandos) para liberar comandos específicos para o chat inteiro, até você desligar. Se um agente pedir um comando bloqueado, o JayV não pergunta a você: a etapa diz quem o bloqueou. O Claude e o Copilot recusam cada comando bloqueado; o Codex, o Cursor e o Kilo não têm lista de comandos, então nesses projetos rodam no modo mais travado. A mudança chega na próxima sincronização."$json$::jsonb),
  ('en', 'docs.commandPermissions.usage', $json$"On the site, open the organization and use the Permissions tab: pick the scope (the whole organization or one repository), check a program to block all of its subcommands or only the subcommands that must not run, add other commands one per line, and save. A repository can only block more than the organization does. In a chat, open Permissions beside the work mode (or Ctrl+K › Command permissions) to allow specific commands for the whole chat until you turn them off. If an agent asks to run a blocked command, JayV does not ask you: the step says who blocked it. Claude and Copilot refuse each blocked command; Codex, Cursor and Kilo have no per-command list, so in these projects they run in their safest mode. The change arrives at the next sync."$json$::jsonb),
  ('es', 'docs.commandPermissions.usage', $json$"En el sitio, abre la organización y usa la pestaña Permisos: elige el alcance (toda la organización o un repositorio), marca un programa para bloquear todos sus subcomandos o solo los que no deben ejecutarse, añade otros comandos, uno por línea, y guarda. Un repositorio solo puede bloquear más que la organización. En el chat, abre Permisos junto al modo de trabajo (o Ctrl+K › Permisos de comandos) para permitir comandos concretos para todo el chat hasta que los desactives. Si un agente pide un comando bloqueado, JayV no te pregunta: el paso indica quién lo bloqueó. Claude y Copilot rechazan cada comando bloqueado; Codex, Cursor y Kilo no tienen lista de comandos, así que en estos proyectos se ejecutan en su modo más restringido. El cambio llega en la próxima sincronización."$json$::jsonb),
  ('zh-CN', 'docs.commandPermissions.usage', $json$"在网站上打开组织，使用“权限”选项卡：选择范围（整个组织或某个仓库），勾选一个程序以阻止它的所有子命令，或只阻止不应运行的子命令，再逐行添加其他命令并保存。仓库只能比组织阻止得更多。在聊天中，打开工作模式旁边的“权限”（或 Ctrl+K › 命令权限），可在整个聊天中允许特定命令，直到你关闭。如果智能体请求被阻止的命令，JayV 不会询问你：该步骤会说明是谁阻止的。Claude 和 Copilot 会拒绝每条被阻止的命令；Codex、Cursor 和 Kilo 没有命令列表，因此在这些项目中以最严格的模式运行。更改会在下次同步时生效。"$json$::jsonb),
  ('hi', 'docs.commandPermissions.usage', $json$"साइट पर संगठन खोलें और अनुमतियाँ टैब इस्तेमाल करें: दायरा चुनें (पूरा संगठन या कोई रिपॉज़िटरी), किसी प्रोग्राम को चिह्नित करके उसके सभी सबकमांड, या केवल वे सबकमांड अवरुद्ध करें जो नहीं चलने चाहिए, अन्य कमांड एक-एक पंक्ति में जोड़ें और सहेजें। रिपॉज़िटरी संगठन से केवल अधिक अवरुद्ध कर सकती है। चैट में कार्य मोड के बगल में अनुमतियाँ खोलें (या Ctrl+K › कमांड अनुमतियाँ) ताकि पूरे चैट के लिए, बंद करने तक, विशिष्ट कमांड की अनुमति दी जा सके। यदि कोई एजेंट अवरुद्ध कमांड माँगता है, तो JayV आपसे नहीं पूछता: चरण बताता है कि उसे किसने अवरुद्ध किया। Claude और Copilot हर अवरुद्ध कमांड को अस्वीकार करते हैं; Codex, Cursor और Kilo में कमांड सूची नहीं होती, इसलिए वे इन प्रोजेक्ट में अपने सबसे सख़्त मोड में चलते हैं। बदलाव अगली सिंक पर पहुँचता है।"$json$::jsonb),
  ('ar', 'docs.commandPermissions.usage', $json$"في الموقع افتح المؤسسة واستخدم تبويب الأذونات: اختر النطاق (المؤسسة كلها أو مستودعًا)، وحدد برنامجًا لحظر كل أوامره الفرعية أو الأوامر الفرعية التي يجب ألا تعمل فقط، وأضف أوامر أخرى، واحدًا في كل سطر، ثم احفظ. لا يستطيع المستودع إلا أن يحظر أكثر مما تحظره المؤسسة. في المحادثة افتح الأذونات بجانب وضع العمل (أو Ctrl+K › أذونات الأوامر) للسماح بأوامر محددة لكامل المحادثة حتى توقفها. إذا طلب وكيل أمرًا محظورًا فلن يسألك JayV: تذكر الخطوة من حظره. يرفض Claude وCopilot كل أمر محظور؛ أما Codex وCursor وKilo فليس لها قائمة أوامر، لذلك تعمل في هذه المشاريع بأكثر أوضاعها تقييدًا. يصل التغيير مع المزامنة التالية."$json$::jsonb),
  ('fr', 'docs.commandPermissions.usage', $json$"Sur le site, ouvrez l'organisation et utilisez l'onglet Autorisations : choisissez la portée (toute l'organisation ou un dépôt), cochez un programme pour bloquer toutes ses sous-commandes ou seulement celles qui ne doivent pas s'exécuter, ajoutez d'autres commandes, une par ligne, puis enregistrez. Un dépôt ne peut que bloquer davantage que l'organisation. Dans le chat, ouvrez Autorisations à côté du mode de travail (ou Ctrl+K › Autorisations de commandes) pour autoriser des commandes précises pour tout le chat, jusqu'à ce que vous les désactiviez. Si un agent demande une commande bloquée, JayV ne vous interroge pas : l'étape indique qui l'a bloquée. Claude et Copilot refusent chaque commande bloquée ; Codex, Cursor et Kilo n'ont pas de liste de commandes, donc dans ces projets ils s'exécutent dans leur mode le plus restreint. Le changement arrive à la prochaine synchronisation."$json$::jsonb),
  ('ru', 'docs.commandPermissions.usage', $json$"На сайте откройте организацию и перейдите на вкладку «Разрешения»: выберите область действия (вся организация или один репозиторий), отметьте программу, чтобы заблокировать все её подкоманды или только те, что не должны выполняться, добавьте другие команды по одной в строке и сохраните. Репозиторий может блокировать только больше, чем организация. В чате откройте «Разрешения» рядом с режимом работы (или Ctrl+K › «Разрешения на команды»), чтобы разрешить отдельные команды для всего чата, пока вы их не отключите. Если агент просит заблокированную команду, JayV вас не спрашивает: шаг показывает, кто её заблокировал. Claude и Copilot отклоняют каждую заблокированную команду; у Codex, Cursor и Kilo нет списка команд, поэтому в таких проектах они работают в самом строгом режиме. Изменение приходит при следующей синхронизации."$json$::jsonb),
  ('ja', 'docs.commandPermissions.usage', $json$"サイトで組織を開き、「許可」タブを使います。範囲（組織全体または一つのリポジトリ）を選び、プログラムにチェックを入れてそのすべてのサブコマンド、または実行してはならないサブコマンドだけをブロックし、ほかのコマンドを一行に一つずつ追加して保存します。リポジトリは組織よりも多くをブロックすることしかできません。チャットでは、作業モードの横の「許可」（または Ctrl+K › コマンド許可）から、チャット全体で、オフにするまで特定のコマンドを許可できます。エージェントがブロックされたコマンドを求めても、JayV はあなたに尋ねません。ステップに誰がブロックしたかが表示されます。Claude と Copilot はブロックされたコマンドをそれぞれ拒否します。コマンド一覧を持たない Codex、Cursor、Kilo は、そのプロジェクトでは最も制限の厳しいモードで動作します。変更は次の同期で届きます。"$json$::jsonb),
  ('de', 'docs.commandPermissions.usage', $json$"Öffnen Sie auf der Website die Organisation und nutzen Sie den Tab Berechtigungen: Wählen Sie den Geltungsbereich (die ganze Organisation oder ein Repository), markieren Sie ein Programm, um alle seine Unterbefehle oder nur die nicht erlaubten zu blockieren, fügen Sie weitere Befehle hinzu, einen pro Zeile, und speichern Sie. Ein Repository kann nur mehr blockieren als die Organisation. Öffnen Sie im Chat neben dem Arbeitsmodus die Berechtigungen (oder Ctrl+K › Befehlsberechtigungen), um bestimmte Befehle für den gesamten Chat, bis Sie sie ausschalten zu erlauben. Fragt ein Agent nach einem blockierten Befehl, fragt JayV Sie nicht: Der Schritt nennt, wer ihn blockiert hat. Claude und Copilot lehnen jeden blockierten Befehl ab; Codex, Cursor und Kilo haben keine Befehlsliste und laufen in diesen Projekten im restriktivsten Modus. Die Änderung kommt bei der nächsten Synchronisierung an."$json$::jsonb)
